  display: inline-flex;
  flex-direction: column;
  gap: 0.4rem;
  font: inherit;
  color: var(--ink);
}

.segmented-label {
  font-size: clamp(0.8rem, 1.2vw, 0.95rem);
  color: var(--muted);
}

.segmented-track {
  display: inline-flex;
  gap: 0.25rem;
  padding: 0.25rem;
  border: 1px solid var(--hair);
  border-radius: 999px;
  background: var(--code-bg);
}

.segmented-option {
  font: inherit;
  font-size: clamp(0.85rem, 1.4vw, 1rem);
  line-height: 1.2;
  white-space: nowrap;
  padding: 0.45rem 1rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease;
}

.segmented-option:hover {
  background: var(--myelin-wash);
}

.segmented-option[aria-checked="true"] {
  background: var(--myelin);
  color: var(--slide);
  font-weight: 600;
}

.segmented-option:focus-visible {
  outline: 3px solid var(--cresyl);
  outline-offset: 3px;
}

:root[data-motion="reduce"] .segmented-option {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .segmented-option {
    transition: none;
  }
}
